+\begin{theorem}[Formalization support for the sub-line distribution]
+	\label{thm:direct-sub-line-distribution}
+	\lean{MIPStarRE.QPBT.SubLineWitness, MIPStarRE.QPBT.exists_subLineWitness}
+	\leanok
+	\uses{def:admissible, def:line, def:line-representative,
+		def:ith-restricted-line, def:combine-map}
+	This auxiliary result is not the source statement of
+	Lemma~\ref{lem:qld-sublines}. Fix admissible $(q,m,d)$ and put
+	$n=2m+2$. Let $D^{\mathrm{dir}}_{\mathrm{Line}}$ be the directly
+	indexed line-point law of \cite{gap:qpbt_ld-dimension-divisibility}:
+	choose a kind and an index $j\in\{1,\dots,n\}$ independently and
+	uniformly, a uniform point $u\in\F_q^n$, and direction $e_j$ in the
+	axis case or a uniform direction with coordinates before $j$ zero in
+	the diagonal case. The line records $j$, its direction $v$, and the
+	canonical base $L_v^{\lnf}(u)$. No hypothesis $n\mid q$ is imposed.
+	There exists a probability distribution $D$ on triples
+	$(\ell,\ell_X,\ell_Z)$, with $\ell$ directly indexed and
+	$\ell_X,\ell_Z$ seed-indexed lines in $\F_q^m$, such that:
+	\begin{enumerate}
+		\item The marginal of $\ell$ is the line marginal of
+		$D^{\mathrm{dir}}_{\mathrm{Line}}$.
+		\item For every triple in the support of $D$, write
+		$\ell=b+\F_q v$, $\ell_X=b_X+\F_q v_X$, and
+		$\ell_Z=b_Z+\F_q v_Z$ with their recorded bases and directions.
+		There are $a_X,c_X,a_Z,c_Z\in\F_q$ such that, for all $t\in\F_q$,
+		\[
+			\operatorname{proj}_X(b+tv)=b_X+(a_X+c_Xt)v_X,
+			\qquad
+			\operatorname{proj}_Z(b+tv)=b_Z+(a_Z+c_Zt)v_Z.
+		\]
+		Thus every point of $\ell$ projects onto both recorded sub-lines,
+		with the affine compatibility of Definition~\ref{def:combine-map}.
+		\item Sample a triple from $D$ and set $u=b_\ell+tv_\ell$ for
+		independent uniform $t\in\F_q$, writing
+		$u=(u_X,u_Z,\alpha,\beta)$. There is a probability vector
+		$(\lambda_{\mathrm v,i,j})$ on
+		$\{\mathrm{ALine},\mathrm{DLine}\}\times\{1,\dots,m\}^2$
+		such that, if $L_{\mathrm v,i}$ denotes the line marginal of
+		$D_{\mathrm v,i}$, the two separate marginal laws are
+		\begin{align*}
+			\mathcal L\big((\ell_X,u_X),\ell_Z\big)
+			&=\sum_{\mathrm v,i,j}\lambda_{\mathrm v,i,j}
+			D_{\mathrm v,i}\otimes L_{\mathrm v,j},\\
+			\mathcal L\big(\ell_X,(\ell_Z,u_Z)\big)
+			&=\sum_{\mathrm v,i,j}\lambda_{\mathrm v,i,j}
+			L_{\mathrm v,i}\otimes D_{\mathrm v,j}.
+		\end{align*}
+		These identities make no assertion of conditional independence of
+		$u_X$ and $u_Z$.
+		\item If $\ell$ is axis-parallel, both $\ell_X$ and $\ell_Z$ are
+		axis-parallel.
+	\end{enumerate}
+	Transport to the seed-indexed extended line-point law in
+	Lemma~\ref{lem:qld-sublines} remains unresolved, as recorded in
+	\cite{gap:qpbt_ld-dimension-divisibility}.
+\end{theorem}
+\begin{proof}
+	\leanok
+	\uses{def:line-representative, def:ith-restricted-line, def:line-point-dist}
+	Sample the extended kind and coordinate index directly. For each source
+	block, use the extended index when it lies in that block and the first
+	coordinate otherwise; choose a seed uniformly in the corresponding
+	fiber of $\chi$. In the axis case use the chosen coordinate direction.
+	In the diagonal case truncate a uniform direction block at that index,
+	reusing the extended direction block whenever its projection is retained.
+	Take canonical representatives of the projected sampled point for the
+	two source bases. All sampling laws are normalized, and forgetting the
+	sub-lines recovers the directly indexed extended line marginal. In each branch,
+	the projected direction is a scalar multiple of the chosen sub-line
+	direction, giving the affine identities and axis closure. Canonical
+	representatives are unchanged along each extended line. Resampling its
+	point therefore preserves the two sub-lines; regrouping the independent
+	point, seed, and direction coordinates gives the two restricted product
+	marginals. Averaging over the branch indices gives their common weights
+	$\lambda_{\mathrm v,i,j}$.
 \end{proof}

